fn split_sections(data: &[u8]) -> (&[u8], &[u8], &[u8]) {
    let mut first = None;
    let mut second = None;
    let mut i = 0usize;
    while i + 1 < data.len() {
        if data[i] == b'\n' && data[i + 1] == b'\n' {
            if first.is_none() {
                first = Some(i);
                i += 2;
                continue;
            }
            second = Some(i);
            break;
        }
        i += 1;
    }

    match (first, second) {
        (Some(a), Some(b)) => (&data[..a], &data[a + 2..b], &data[b + 2..]),
        (Some(a), None) => (&data[..a], &data[a + 2..], &[]),
        (None, _) => (data, &[], &[]),
    }
